// TestSearchSpecs pins the interactive search spec (identify-match-override):
// the bounded anime search endpoint under the anonymous-tier contract —
// app-named User-Agent, 700 ms pacing, string-only variables (no secrets),
// {placeholder} substitution only — with the optional kind narrowing.
func TestSearchSpecs(t *testing.T) {
	cases := []struct {
		name      string
		req       *metadatav1.SearchSpecsRequest
		wantURL   string
		wantKinds map[string]bool // the variable names the spec must carry
	}{
		{
			name:      "title_only_no_kind",
			req:       &metadatav1.SearchSpecsRequest{Query: "aria"},
			wantURL:   "https://shikimori.io/api/animes?search={query}&limit=10",
			wantKinds: map[string]bool{"query": true},
		},
		{
			name:      "kind_narrows_the_search",
			req:       &metadatav1.SearchSpecsRequest{Query: "aria", Kind: "tv"},
			wantURL:   "https://shikimori.io/api/animes?search={query}&limit=10&kind={kind}",
			wantKinds: map[string]bool{"query": true, "kind": true},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res, err := (&sourceImpl{}).SearchSpecs(context.Background(), tc.req)
			if err != nil {
				t.Fatalf("SearchSpecs: %v", err)
			}
			spec := res.GetSpec()
			if spec.GetMethod() != "GET" {
				t.Errorf("method = %q, want GET", spec.GetMethod())
			}
			if spec.GetUrlTemplate() != tc.wantURL {
				t.Errorf("url_template = %q, want %q", spec.GetUrlTemplate(), tc.wantURL)
			}
			if ua := spec.GetHeaders()["User-Agent"]; ua != userAgent {
				t.Errorf("User-Agent = %q, want %q", ua, userAgent)
			}
			if spec.GetMinIntervalMs() != minIntervalMS {
				t.Errorf("min_interval_ms = %d, want %d", spec.GetMinIntervalMs(), minIntervalMS)
			}
			got := map[string]bool{}
			for name, v := range spec.GetVariables() {
				got[name] = true
				if v.GetRedactedRef() != "" {
					t.Errorf("variable %q carries redacted_ref %q — the anonymous tier emits string values only", name, v.GetRedactedRef())
				}
			}
			for name := range tc.wantKinds {
				if !got[name] {
					t.Errorf("variable %q missing, spec carries %v", name, got)
				}
			}
			if len(got) != len(tc.wantKinds) {
				t.Errorf("variables = %v, want exactly %v", got, tc.wantKinds)
			}
			for name, v := range spec.GetVariables() {
				if v.GetStringValue() == "" {
					t.Errorf("variable %q is empty — the search is shaped by the title only", name)
				}
			}
		})
	}
}

// TestSearchResults pins the candidate conversion (identify-match-override):
// payload order verbatim, convention fields carried where the payload carries
// them, honest proto-presence absence where it does not, no re-scoring.
func TestSearchResults(t *testing.T) {
	cases := []struct {
		name    string
		req     *metadatav1.SearchResultsRequest
		want    []*metadatav1.SearchCandidate
		wantErr string
	}{
		{
			name: "payload_order_and_fields_verbatim",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: true,
				Body: []byte(`[
					{"id":378,"name":"Aria the Animation","russian":"Ария: Анимация","kind":"tv",
					 "year":2005,"episodes":13,"image":{"original":"/uploads/anime/original/378.jpg"}},
					{"id":40709,"name":"Wake Up, Aria!","kind":"ova"}
				]`),
			}},
			want: []*metadatav1.SearchCandidate{
				{
					ExternalId: "378", Title: "Aria the Animation", Kind: "tv",
					RussianTitle: proto.String("Ария: Анимация"),
					Year:         proto.Int32(2005),
					Episodes:     proto.Int32(13),
					Poster:       proto.String("https://shikimori.io/uploads/anime/original/378.jpg"),
				},
				{ExternalId: "40709", Title: "Wake Up, Aria!", Kind: "ova"},
			},
		},
		{
			name: "valid_empty_list_zero_candidates",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: true, Body: []byte(`[]`),
			}},
			want: []*metadatav1.SearchCandidate{},
		},
		{
			name: "failed_fetch_is_an_error",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: false, Error: "upstream 503",
			}},
			wantErr: "upstream 503",
		},
		{
			name: "unparsable_body_is_an_error",
			req: &metadatav1.SearchResultsRequest{Fetched: &metadatav1.FetchedResponse{
				Fetched: true, Body: []byte(`{"surprise":true}`),
			}},
			wantErr: "not a list",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res, err := (&sourceImpl{}).SearchResults(context.Background(), tc.req)
			if tc.wantErr != "" {
				if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
					t.Fatalf("err = %v, want containing %q", err, tc.wantErr)
				}
				return
			}
			if err != nil {
				t.Fatalf("SearchResults: %v", err)
			}
			got := res.GetCandidates()
			if len(got) != len(tc.want) {
				t.Fatalf("candidates = %d, want %d", len(got), len(tc.want))
			}
			for i, w := range tc.want {
				g := got[i]
				if g.ExternalId != w.ExternalId || g.Title != w.Title || g.Kind != w.Kind {
					t.Errorf("candidate %d = {%s %s %s}, want {%s %s %s}",
						i, g.ExternalId, g.Title, g.Kind, w.ExternalId, w.Title, w.Kind)
				}
				if !equalOpt(g.RussianTitle, w.RussianTitle) {
					t.Errorf("candidate %d russian_title = %v, want %v", i, g.RussianTitle, w.RussianTitle)
				}
				if (g.Year == nil) != (w.Year == nil) || (g.Year != nil && *g.Year != *w.Year) {
					t.Errorf("candidate %d year = %v, want %v", i, g.Year, w.Year)
				}
				if (g.Episodes == nil) != (w.Episodes == nil) || (g.Episodes != nil && *g.Episodes != *w.Episodes) {
					t.Errorf("candidate %d episodes = %v, want %v", i, g.Episodes, w.Episodes)
				}
				if (g.Poster == nil) != (w.Poster == nil) || (g.Poster != nil && *g.Poster != *w.Poster) {
					t.Errorf("candidate %d poster = %v, want %v", i, g.Poster, w.Poster)
				}
			}
		})
	}
}

// equalOpt compares two optional string fields: absent/absent and value/value
// are equal, absent/value is not.
func equalOpt(a, b *string) bool {
	if a == nil || b == nil {
		return a == b
	}
	return *a == *b
}
